#!/usr/bin/env bash
#
# a update — pull the newest version of a.
#
# AI DISCLOSURE: This script was entirely generated by an AI tool
set -uo pipefail
source "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/lib/common.sh"
source "$A_LIB/update.sh"

usage() {
  cat <<USAGE
a update

Fetches the latest version of a and fast-forwards the install at
$A_ROOT. Local edits to the install are never overwritten: if the
checkout has diverged the update stops and says so.
USAGE
}

case "${1:-}" in
  -h|--help|help) usage; exit 0 ;;
  "") ;;
  *) log "a update: takes no arguments"; usage >&2; exit 1 ;;
esac

banner "UPDATE" "a update" ""

a_is_git_install || die "$A_ROOT is not a git checkout. Reinstall with the one-liner from the README."

before="$(a_git rev-parse --short HEAD)"
a_git fetch --quiet || die "could not reach $(a_git remote get-url origin 2>/dev/null || echo the remote)"
touch "$A_ROOT/.git/a-last-update-check" 2>/dev/null

behind="$(a_commits_behind)"
if [[ "${behind:-0}" -eq 0 ]]; then
  ok "already up to date ($before)"
  exit 0
fi

a_git merge --ff-only --quiet '@{u}' 2>/dev/null \
  || die "could not fast-forward $A_ROOT — it has local changes. Resolve them with git, then rerun: a update"

after="$(a_git rev-parse --short HEAD)"
a_git --no-pager log --format=" ${DIM}%h${RESET} %s" "$before..$after"
printf '\n'
ok "updated $before → $after ($behind new commit$([[ "$behind" -eq 1 ]] || printf s))"
